code='''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    bg = max(set(x for row in grid for x in row), key=lambda c: sum(row.count(c) for row in grid))
    markers = {(r, c) for r in range(h) for c in range(w) if grid[r][c] != bg}
    fill = 3
    for r in range(h):
        cols = [c for rr, c in markers if rr == r]
        if len(cols) >= 2:
            for c in range(min(cols) + 1, max(cols)):
                if grid[r][c] == bg:
                    out[r][c] = fill
    for c in range(w):
        rows = [r for r, cc in markers if cc == c]
        if len(rows) >= 2:
            for r in range(min(rows) + 1, max(rows)):
                if grid[r][c] == bg:
                    out[r][c] = fill
    return out
'''
